import path from 'node:path';
import {writeFile} from 'node:fs/promises';
export async function assertProductHeaderLine({page,frame,check,out,context}){
 const root=frame.locator('#ui032'),title=root.locator('.page-head h1'),text=await title.textContent();
 for(const [width,height]of [[1280,820],[1024,820],[820,640]]){
  await page.setViewportSize({width,height});const measurements=await root.locator('.product-heading-line').evaluate(el=>{const nodes=['#u32-back','.crumb','.page-head h1','.product-title-note','#u32-availability-status'].map(s=>el.querySelector(s)||el.closest('#ui032').querySelector(s)),rects=nodes.map(n=>{const r=n.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,center:r.y+r.height/2};});return{rects,row:el.getBoundingClientRect().toJSON(),titleStyle:{font:getComputedStyle(nodes[2]).fontSize,weight:getComputedStyle(nodes[2]).fontWeight},order:el.querySelector('.crumb').nextElementSibling.className};});
  const [back,crumb,heading,help,state]=measurements.rects;check(Math.max(...[back,heading,help,state].map(r=>r.center))-Math.min(...[back,heading,help,state].map(r=>r.center))<=1,`${context} ${width}返回/编号/说明/状态垂直同排`);check(back.x+back.width<=heading.x&&heading.x+heading.width<=help.x&&help.x+help.width<=state.x,`${context} ${width}导航到状态顺序正确且不重叠`);check(state.x+state.width<=measurements.row.x+measurements.row.width+1,`${context} ${width}状态完整位于内容区`);check(measurements.titleStyle.font==='20px'&&measurements.titleStyle.weight==='600',`${context} ${width}保留标题字号字重`);await writeFile(path.join(out,`header-${context}-${width}.json`),JSON.stringify(measurements,null,2));await page.screenshot({path:path.join(out,`header-${context}-${width}.png`)});await root.locator('.product-heading-line').screenshot({path:path.join(out,`header-${context}-topline-${width}.png`)});
 }
 await title.evaluate(el=>{el.textContent='一个很长的商品编号用于验证头部布局ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';});const overflow=await root.locator('.product-heading-line').evaluate(el=>{const h=el.querySelector('h1'),badge=el.querySelector('#u32-availability-status'),back=el.querySelector('#u32-back');return{ellipsis:getComputedStyle(h).textOverflow,nowrap:getComputedStyle(h).whiteSpace,clipped:h.scrollWidth>h.clientWidth,badge:badge.getBoundingClientRect().toJSON(),row:el.getBoundingClientRect().toJSON(),back:back.getBoundingClientRect().toJSON()};});check(overflow.ellipsis==='ellipsis'&&overflow.nowrap==='nowrap'&&overflow.clipped,'长商品编号仅自身省略，保留完整文本语义');check(overflow.badge.x+overflow.badge.width<=overflow.row.x+overflow.row.width+1&&Math.abs(overflow.badge.y+overflow.badge.height/2-overflow.back.y-overflow.back.height/2)<=1,'长商品编号不挤走状态或返回按钮');await page.screenshot({path:path.join(out,`header-${context}-long-820.png`)});await title.evaluate((el,text)=>{el.textContent=text;},text);
 const help=root.getByRole('button',{name:'商品资料说明',exact:true});await help.click();const description=frame.getByRole('dialog').filter({has:page.getByRole('heading',{name:'商品资料说明',exact:true})});await description.waitFor();check((await description.textContent()).includes('来源'),context+'合并后仍能打开完整商品说明');await page.keyboard.press('Escape');await description.waitFor({state:'detached'});check(await help.evaluate(el=>el.ownerDocument.activeElement===el),context+'说明关闭后焦点返回原按钮');await page.setViewportSize({width:1280,height:820});
}
